        "text": "credit_widen 锚维持 on，但已经到了「一周之内可能翻面」的程度：HY OAS **3.34%**(日 +11bp、周 **0bp**、月 +3bp、96 分位)，30 日均值 3.27，高出 **7bp**(上期 9bp、上上期 14bp、三周前 27bp)。★ 上期那条「六档周线第一次全线收窄(四个月来首次)」**本期没有延续**：本周周线是 HY 0 / B **+7** / CCC -1 / BB -4 / BBB -1 / IG -1——几乎不动，只有 B 独自走阔。**单周收敛被证伪为噪音，而不是拐点**，这也是上期把「喘息」与「拐点」并列、不当场改判的价值所在。★ 本期新出现、且比余量更重要的形态是**月线首次方向分化**：BB **-7bp**(1.96%)与 B **+22bp**(3.57%)反向，CCC +13bp(13.10%、半年 **+371bp**)、BBB +6bp、IG +5bp、HY +3bp。前三期的形态是「沿阶梯整体上移一格」(CCC 回补 → B 加速 → 高等级不动)，本期是**裂缝出现在 B 与 BB 之间**：同一批投资人开始区分「BB 还能扛」与「B 开始不行」。这个区分的意义比指数本身大——B 是真正会新增违约的那一层，BB 多数还能再融资。若下一期 BB 转正而 B 继续加速，则是「压力突破 BB 防线」；若 BB 继续收窄、B 也回落，则是「B 层出清完成」。★ 反证必须并写：NFCI **-0.46**(周 +0.03)仍在宽松区、SLOOS 1.7「混合」、HYG 76.63(月 -0.26%、**0 分位**)、LQD 102.74(月 -0.14%)——**ETF 层面仍无抛售，动的是 OAS 定价**。裁决点：HY 是否跌破 30 日均值 **3.27**。跌破即锚转 off、price_split 掉到 2/3、growth 与 breadth 的判定同时松动，主导权将在滞胀档(2/2)与 real_rate_shock(取决于 10Y 月线是否越过 +5bp)之间决定。口径限制：违约率 TTM 1.9%(93 分位)为 2026-04 vintage，不能用于否认当期利差，也不能用于预测违约。"
